#include "runner_attachments.h"
#include <cassert>
#include <filesystem>
#include <iostream>
namespace sr=suitecut::runner;namespace af=sr::attachment_files;namespace fs=std::filesystem;
struct Proof {
 sr::StepOwner owner{1,1,0,1,1,1,getpid(),"body"};sr::TestSteps steps;fs::path root;std::vector<std::vector<std::string>> packets;std::vector<std::string> failures;sr::RunnerAttachments files;uint64_t request=0;bool missing_step=false;
 Proof(fs::path path):root(std::move(path)),files(root,{[this](const auto& line){packets.push_back(af::Fields(line));},[this](const auto& error){failures.push_back(error);},[this](uint64_t id){return missing_step?nullptr:steps.Find(id);}}){const auto now=af::Now();assert(steps.Open(owner,now+5000,now));files.WorkerStarted();files.BeginCallback(owner,now+5000,now);}
 uint64_t Step(uint64_t parent=0,uint64_t timeout=0){auto id=steps.Begin(owner,parent,"\"actual native local file step\"",timeout,af::Now());assert(id);return *id;}
 void Begin(uint64_t id){assert(files.Packet({"ATTACH_STEP_BEGIN",std::to_string(++request),"0","1","1",std::to_string(id),"6100","B","0","~","-"},af::Now(),false));}
 void Events(){for(const auto& e:steps.TakeEvents())files.StepChanged(*steps.Find(e.id),af::Now());}
 void Skip(uint64_t id,uint64_t cause){const auto now=af::Now();assert(files.CanAcceptLocalSkip(owner,id,now));assert(steps.SkipStep(owner,id,cause,"\"actual local reason\\ud800\"",true,now));files.AcceptLocalSkip(owner,id,cause,now);Events();}
 void Fence(uint64_t id,bool& forwarded,uint64_t cause=0){assert(steps.Receive(owner,id,true,"\"\"",af::Now(),0,cause));files.FenceStep(owner,id,[&,id](const auto& error){assert(!error);assert(steps.Complete(owner,id,af::Now(),error));forwarded=true;},af::Now());}
 void Drain(bool finish){size_t cursor=0;const auto cap=af::Now()+7000;while(files.Physical()){assert(af::Now()<cap);files.Tick(af::Now());while(cursor<packets.size()){const auto p=packets[cursor++];if(finish&&p[0]=="ATTACH_STEP_ADMITTED"&&p[7]=="1")files.Packet({"ATTACH_FINISH",p[5],"0","1","1"},af::Now(),false);}if(files.Physical())poll(nullptr,0,1);}assert(failures.empty());}
 bool Terminal(uint64_t id,uint64_t cause,uint64_t source)const{for(const auto&p:packets)if(p[0]=="ATTACH_STEP_LOCAL_SKIP_RESULT"&&p[6]==std::to_string(id)&&p[7]==std::to_string(cause)&&p[8]==std::to_string(source)&&p[9]=="-")return true;return false;}
 void Empty()const{assert(files.Records().empty());if(fs::exists(root))for(const auto&p:fs::recursive_directory_iterator(root))assert(!p.is_regular_file());}
};
int main(int argc,char**argv){
 if(argc==2&&std::string_view(argv[1])=="--native-attachment-worker")return af::Worker();
 if(argc==2&&std::string_view(argv[1])=="--native-attachment-cleanup")return af::Cleanup();
 char temp[]="/tmp/suitecut-native-local-step-files-XXXXXX";assert(mkdtemp(temp));const fs::path root=temp;unsigned groups=0;
 {Proof p(root/"actual-cause");const auto id=p.Step();p.Begin(id);p.Skip(id,19);assert(p.files.Physical()==1&&p.steps.Find(id)->receipt==sr::StepReceipt::Pending);bool done=false;p.Fence(id,done,19);assert(!done);p.Drain(false);assert(done&&p.Terminal(id,19,id)&&p.steps.Find(id)->receipt_step_skip==19);p.Empty();++groups;}
 {Proof p(root/"descendants-not-siblings");const auto source=p.Step(),child=p.Step(source),sibling=p.Step();p.Begin(child);p.Begin(sibling);p.Skip(source,21);assert(p.steps.Find(child)->status==sr::StepStatus::Skipped&&p.steps.Find(sibling)->status==sr::StepStatus::Running);bool parent_done=false,child_done=false,sibling_done=false;p.Fence(source,parent_done,21);p.Fence(child,child_done,21);p.Fence(sibling,sibling_done);assert(!parent_done&&!child_done&&!sibling_done);p.Drain(true);assert(parent_done&&child_done&&sibling_done&&p.Terminal(child,21,source));assert(p.files.Records().size()==1&&p.files.Records()[0].step_id==sibling&&p.steps.Find(source)->receipt_step_skip==21&&p.steps.Find(child)->receipt_step_skip==21);++groups;}
 {Proof p(root/"forged-before-native-step-cause");const auto id=p.Step();p.Begin(id);auto wrong=p.owner;wrong.scope_generation=2;assert(!p.files.CanAcceptLocalSkip(wrong,id,af::Now()));bool rejected=false;try{p.files.AcceptLocalSkip(p.owner,id,3,af::Now());}catch(const std::runtime_error&){rejected=true;}assert(rejected&&p.files.Physical()==1&&p.steps.Find(id)->status==sr::StepStatus::Running);bool done=false;p.Fence(id,done);p.Drain(true);assert(done&&p.files.Records().size()==1);++groups;}
 {Proof p(root/"original-deadline");const auto id=p.Step(0,100);p.Begin(id);while(af::Now()<p.steps.Find(id)->deadline)poll(nullptr,0,1);p.steps.Tick(af::Now());p.Events();assert(!p.files.CanAcceptLocalSkip(p.owner,id,af::Now())&&!p.steps.Find(id)->step_skip);bool done=false;p.Fence(id,done);p.Drain(false);assert(done&&p.steps.Find(id)->status==sr::StepStatus::TimedOut);p.Empty();++groups;}
 {Proof p(root/"real-prior-callback-error");const auto id=p.Step();p.Begin(id);assert(p.steps.Receive(p.owner,id,false,"\"actual original callback error\"",af::Now()));p.Events();assert(!p.files.CanAcceptLocalSkip(p.owner,id,af::Now()));bool done=false;p.files.FenceStep(p.owner,id,[&](const auto& error){assert(p.steps.Complete(p.owner,id,af::Now(),error));done=true;},af::Now());p.Drain(false);assert(done&&p.steps.Find(id)->status==sr::StepStatus::Failed&&!p.steps.Find(id)->step_skip&&p.steps.Find(id)->error_json=="\"actual original callback error\"");p.Empty();++groups;}
 {Proof p(root/"prior-test-skip");const auto id=p.Step();p.Begin(id);const auto now=af::Now();p.files.AcceptTestSkip(0,1,1,5,"\"actual accepted test cause\"",now);assert(p.steps.SkipTestCallback(p.owner,5,"\"actual accepted test cause\"",now));p.Events();assert(!p.files.CanAcceptLocalSkip(p.owner,id,af::Now())&&!p.steps.Find(id)->step_skip);assert(p.steps.Receive(p.owner,id,true,"\"\"",af::Now(),5));bool done=false;p.files.FenceStep(p.owner,id,[&](const auto& error){assert(!error&&p.steps.Complete(p.owner,id,af::Now(),error));done=true;},af::Now());p.Drain(false);assert(done&&p.steps.Find(id)->receipt_test_skip==5);p.Empty();++groups;}
 {Proof p(root/"wrong-accepted-request");const auto id=p.Step();p.Begin(id);const auto now=af::Now();assert(p.steps.SkipStep(p.owner,id,7,"\"native original cause\"",true,now));bool rejected=false;try{p.files.AcceptLocalSkip(p.owner,id,9,now);}catch(const std::runtime_error&){rejected=true;}assert(rejected&&p.files.Physical()==1);p.files.AcceptLocalSkip(p.owner,id,7,now);p.Events();bool done=false;p.Fence(id,done,7);p.Drain(false);assert(done&&p.Terminal(id,7,id));p.Empty();++groups;}
 {Proof p(root/"later-test-cause-coexists-with-real-local-cancellation");const auto id=p.Step();p.Begin(id);p.Skip(id,7);const auto now=af::Now();assert(p.files.CanAcceptTestSkip(0,1,1,9,now));p.files.AcceptTestSkip(0,1,1,9,"\"actual later test cause\"",now);assert(p.steps.SkipTestCallback(p.owner,9,"\"actual later test cause\"",now));p.Events();bool done=false;p.Fence(id,done,7);p.Drain(false);assert(done&&p.steps.Find(id)->test_skip->request==9&&p.steps.Find(id)->step_skip->request==7&&p.steps.Find(id)->receipt_step_skip==7);bool terminal=false;for(const auto&v:p.packets)if(v[0]=="ATTACH_STEP_TEST_SKIP_RESULT"&&v[6]==std::to_string(id)&&v[7]=="9")terminal=true;assert(terminal&&!p.Terminal(id,7,id));p.Empty();++groups;}
 {Proof p(root/"observed-raw-error-retains-priority-over-later-test-skip");const auto id=p.Step();p.Begin(id);p.Skip(id,7);assert(p.steps.Receive(p.owner,id,false,"\"actual raw cleanup error\"",af::Now()));assert(!p.files.CanAcceptTestSkip(0,1,1,9,af::Now()));bool done=false;p.files.FenceStep(p.owner,id,[&](const auto& error){assert(!error&&p.steps.Complete(p.owner,id,af::Now(),error));done=true;},af::Now());p.Drain(false);assert(done&&p.steps.Find(id)->receipt_error_json=="\"actual raw cleanup error\""&&!p.steps.Find(id)->receipt_ok&&!p.steps.Find(id)->test_skip);p.Empty();++groups;}
 {Proof p(root/"missing-step-preflight");const auto id=p.Step();p.Begin(id);p.missing_step=true;assert(!p.files.CanAcceptTestSkip(0,1,1,9,af::Now())&&p.files.Physical()==1);p.missing_step=false;assert(!p.steps.Find(id)->test_skip&&p.steps.Find(id)->status==sr::StepStatus::Running);bool done=false;p.Fence(id,done);p.Drain(true);assert(done&&p.files.Records().size()==1);++groups;}
 fs::remove_all(root);std::cout<<"PASS"<<groups<<" actual native local-step attachment cause/subtree/receipt/priority groups\n";
}
